window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[117]={"id":"117","numero":117,"titre":"Psoriasis","objectifs":[{"id":"117-1","rang":"B","rubrique":"Épidémiologie","titre":"Connaître la fréquence du psoriasis dans la population française","contenu":"<table >\n        <thead><tr><th>Item</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Prévalence</span></strong></td>\n            <td><span class=\"kw-def\">Touche <strong>2 à 3 %</strong> de la population française</span> — dermatose <span class=\"kw-etio\">inflammatoire</span> chronique fréquente.</td>\n          </tr>\n          <tr>\n            <td><strong>Sex-ratio</strong></td>\n            <td>Atteinte équilibrée homme / femme.</td>\n          </tr>\n          <tr>\n            <td><strong>Âge de début</strong></td>\n            <td>Adolescent ou adulte jeune le plus souvent ; un <strong>début précoce</strong> est associé aux <span class=\"kw-clinique\">gènes de susceptibilité</span> et à une <strong><span class=\"kw-clinique\">évolution</span> plus sévère</strong> que les formes débutant après la cinquantaine.</td>\n          </tr>\n          <tr>\n            <td><strong>Rhumatisme psoriasique</strong></td>\n            <td><span class=\"kw-def\">Prévalence</span> en population générale <strong><span class=\"kw-chiffre\">0,2 à 0,4 %</span></strong> · présent chez <strong><span class=\"kw-chiffre\">5 à 25 %</span></strong> des patients psoriasiques.</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 114 — Exanthème et érythrodermie · 197 — <span class=\"kw-def\">Spondyloarthrite</span> · 196 — <span class=\"kw-def\">Polyarthrite rhumatoïde</span></em></p>","frequence":0},{"id":"117-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie du psoriasis","contenu":"<p>Maladie multifactorielle : <span class=\"kw-def\">interactions entre système immunitaire, kératinocytes et vaisseaux</span> sur un <strong><span class=\"kw-def\">terrain</span> <span class=\"kw-etio\">génétique</span> particulier</strong>. Origine exacte inconnue, mais prédisposition <span class=\"kw-etio\">génétique</span> certaine.</p>\n\n      <h4>Définition mécanistique</h4>\n      <div class=\"callout callout-info\">\n        Dermatose <span class=\"kw-etio\">inflammatoire</span> érythémato-squameuse chronique caractérisée par un <strong>renouvellement épidermique accéléré</strong> avec hyperprolifération + troubles de la <span class=\"kw-bio\">différenciation</span> des kératinocytes.\n      </div>\n\n      <h4>Prédisposition <span class=\"kw-etio\">génétique</span></h4>\n      <ul>\n        <li>Nombreux gènes de susceptibilité identifiés</li>\n        <li>Gènes associés au groupe <strong>HLA</strong></li>\n        <li>Gènes associés à l’<strong>immunité innée</strong></li>\n        <li>Gènes associés à l’<strong>immunité <span class=\"kw-etio\">acquise</span></strong></li>\n      </ul>\n\n      <h4>Cascade physiopathologique (3 étapes)</h4>\n      <table class=\"matrix\">\n        <thead><tr><th>Étape</th><th>Acteurs</th><th>Conséquence</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1. Trigger</strong></td>\n            <td>Stress, traumatismes cutanés (<span class=\"kw-clinique\">phénomène de Koebner</span>), germes, médicaments</td>\n            <td>Kératinocytes produisent : peptides antimicrobiens (<strong>cathélicidine LL-37</strong>) et cytokines pro-inflammatoires (<strong>IL-1β</strong>, <strong>IL-36</strong>, <strong>TNFα</strong>)</td>\n          </tr>\n          <tr>\n            <td><strong>2. Activation</strong></td>\n            <td>Cathélicidine, IL-1β, IL-36, TNFα</td>\n            <td>\n              → Stimulation de l’<strong>interféron α</strong><br>\n              → Activation des <strong>cellules dendritiques</strong> qui produisent <strong>IL-12</strong> et <strong>IL-23</strong><br>\n              → <span class=\"kw-bio\">Différenciation</span> LT en <strong>Th1</strong> (qui produit l’<strong>INFγ</strong>) et <strong>Th17</strong> (qui produit l’<strong>IL-17</strong>)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>3. Action terminale</strong></td>\n            <td><strong>IL-12, IL-17, TNFα</strong></td>\n            <td>\n              → <span class=\"kw-clinique\">Prolifération des kératinocytes</span><br>\n              → <span class=\"kw-clinique\">Néo-angiogenèse</span><br>\n              → Chimiokines → <span class=\"kw-clinique\">recrutement des PNN</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>⭐ <span class=\"kw-bio\">Anatomopathologie</span> (rang B)</strong> — la <span class=\"kw-bio\">biopsie</span> cutanée <strong>n’est pas nécessaire en routine</strong>, mais peut être utile en cas de doute :\n        <ul>\n          <li><strong>Épiderme</strong> : <span class=\"kw-clinique\">hyperkératose</span> avec <strong><span class=\"kw-clinique\">parakératose</span></strong> (maturation anormale), <strong><span class=\"kw-clinique\">acanthose</span></strong> par hyperprolifération (à distinguer d’<span class=\"kw-clinique\">acantholyse</span>), <strong>micro-<span class=\"kw-clinique\">abcès</span> épidermique à PNN de Munro-Sabouraud</strong></li>\n          <li><strong>Derme</strong> : infiltrat lymphocytaire, <strong>allongement des papilles dermiques</strong> (hyperpapillomatose), vaisseaux néoformés dilatés</li>\n        </ul>\n      </div>\n\n      <h4>Cibles thérapeutiques des biothérapies (corrélation physiopath ↔ traitement)</h4>\n      <ul>\n        <li><strong>TNFα</strong> : <span class=\"kw-ttt\">étanercept</span>, <span class=\"kw-ttt\">infliximab</span>, <span class=\"kw-ttt\">adalimumab</span>, certolizumab</li>\n        <li><strong>IL-17</strong> : sécukinumab, ixékizumab, brodalumab</li>\n        <li><strong>IL-12 / IL-23</strong> (sous-unité p40) : <span class=\"kw-ttt\">ustékinumab</span></li>\n        <li><strong>IL-23</strong> (sous-unité p19) : <span class=\"kw-ttt\">guselkumab</span>, rizankizumab, tildrakizumab</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 197 — <span class=\"kw-def\">Spondyloarthrite</span></em></p>","frequence":1},{"id":"117-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’un psoriasis en plaques classique","contenu":"<div class=\"obj-callout success\">\n        ✅ Diagnostic <strong>clinique</strong> dans la très grande majorité des cas. <span class=\"kw-bio\">Biopsie</span> indiquée <strong>seulement en cas de doute diagnostique</strong> devant des lésions atypiques.\n      </div>\n\n      <h4><span class=\"kw-clinique\">Lésion</span> élémentaire</h4>\n      <table >\n        <thead><tr><th>Caractéristique</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Type</strong></td>\n            <td><span class=\"kw-def\">Papule érythémato-squameuse</span> : bien limitée, arrondie, ovalaire ou polycyclique.</td>\n          </tr>\n          <tr>\n            <td><strong>Squames</strong></td>\n            <td>\n              Soit couche <strong>très épaisse</strong><br>\n              Soit couche <strong>partiellement décapée</strong> par le traitement (laissant apparaître l’<span class=\"kw-clinique\">érythème</span> sous-jacent)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Taille</strong></td>\n            <td>\n              Variable :\n              <ul>\n                <li><span class=\"kw-clinique\">Psoriasis</span> en <strong>plaques</strong></li>\n                <li><span class=\"kw-clinique\">Psoriasis</span> <strong><span class=\"kw-clinique\">nummulaire</span></strong> (forme de pièce de monnaie)</li>\n                <li><span class=\"kw-clinique\">Psoriasis</span> en <strong>gouttes</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>⭐ Signes du grattage</strong></td>\n            <td><strong>Tache de bougie</strong> : blanchiment de la <span class=\"kw-clinique\">plaque</span> après grattage ; <span class=\"kw-def\">suivi</span> d’une <strong>rosée sanglante</strong> (signe d’Auspitz).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Localisations habituelles ⭐ « zones bastions »</h4>\n      <p><span class=\"kw-clinique\">Éruption</span> <strong>multiple</strong> et <strong>symétrique</strong>, parfois diffuse. Zones exposées aux frottements et traumatismes :</p>\n      <ul>\n        <li><strong>Coudes</strong> · bord cubital de l’avant-bras</li>\n        <li><strong>Genoux</strong> · jambes</li>\n        <li><strong>Région lombo-sacrée</strong></li>\n        <li><strong>Cuir chevelu</strong></li>\n        <li>Ongles · paumes · plantes</li>\n        <li>Discrètes : ombilic · conduit auditif externe</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        ⭐ <strong>Respect habituel du visage</strong> dans la forme classique. Si atteinte faciale → forme particulière : <strong>sébo-<span class=\"kw-clinique\">psoriasis</span></strong>.\n      </div>\n\n      <h4>Symptômes &amp; signes associés</h4>\n      <table >\n        <tbody>\n          <tr>\n            <td><strong>État général</strong></td>\n            <td>Conservé (formes habituelles).</td>\n          </tr>\n          <tr>\n            <td><strong>Contagiosité</strong></td>\n            <td>❌ <strong>Non contagieux</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Prurit</span></strong></td>\n            <td><span class=\"kw-clinique\">Prurit lors des poussées dans <strong>60 %</strong> des cas</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Gêne fonctionnelle</strong></td>\n            <td>Lésions parfois douloureuses (paumes, plantes) → <strong>fissures</strong> possibles.</td>\n          </tr>\n          <tr>\n            <td><strong>Séquelles</strong></td>\n            <td>Régression <strong>sans cicatrice</strong> · parfois macules hyperpigmentées ou dépigmentées.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-clinique\">Évolution</span></h4>\n      <ul>\n        <li>Chronique, quasi-continue (formes sévères) ou par <strong>poussées entrecoupées de rémissions</strong></li>\n        <li><strong>Rémissions plus fréquentes l’été</strong> (effet bénéfique des <span class=\"kw-etio\">UV</span>)</li>\n        <li>Poussées souvent imprévisibles, déclenchées par : <strong>facteurs psychologiques</strong>, <strong>infections ORL</strong>, <strong>médicaments</strong></li>\n        <li><strong>Phénomène de Koebner</strong> : traumatismes cutanés (griffures, vaccination, <span class=\"kw-ttt\">chirurgie</span>, <span class=\"kw-etio\">coups de soleil</span>) aggravent le <span class=\"kw-clinique\">psoriasis</span></li>\n      </ul>\n\n      <h4>Complications</h4>\n      <ul>\n        <li><strong>Surinfection</strong> : le plus souvent à <span class=\"kw-etio\">Candida albicans</span> (plis) ou à <span class=\"kw-etio\">dermatophytes</span> (paumes, plantes) 🍄 ; plus rarement <span class=\"kw-etio\">bactérienne</span></li>\n        <li><strong>Eczématisation</strong> : à évoquer si <strong>suintement</strong> + <span class=\"kw-clinique\">prurit intense</span> → rechercher une sensibilisation ou une irritation par un topique <span class=\"kw-etio\">médicamenteux</span></li>\n      </ul>\n\n      <h4>Facteurs déclenchants / aggravants</h4>\n      <table class=\"matrix\">\n        <thead><tr><th>Famille</th><th>Détails</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Infections</strong></td>\n            <td>\n              <ul>\n                <li>Épisodes <span class=\"kw-etio\">infectieux</span> peuvent aggraver un <span class=\"kw-clinique\">psoriasis</span> connu</li>\n                <li><strong><span class=\"kw-etio\">VIH</span></strong> : peut entraîner la survenue ou l’aggravation</li>\n                <li>Épisodes rhino-pharyngés (virus, <strong><span class=\"kw-etio\">streptocoque</span> β-hémolytique du groupe A</strong>) — mode de début fréquent du <span class=\"kw-clinique\">psoriasis</span> en gouttes chez l’enfant 👦🏻</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Médicaments</strong></td>\n            <td>\n              <ul>\n                <li><strong>β-bloquants</strong></li>\n                <li>Rôle débattu (à ne pas cocher en annale) : <span class=\"kw-ttt\">lithium</span>, <span class=\"kw-ttt\">sartans</span>, <span class=\"kw-ttt\">IEC</span>, anti-TNFα</li>\n                <li><strong>Arrêt d’une <span class=\"kw-ttt\">corticothérapie</span> générale</strong> : risque de <strong>rebond important</strong> voire de <strong>forme grave</strong> (érythrodermie, pustuleux généralisé)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Psychologique</strong></td>\n            <td>Chocs émotionnels, stress (sécrétion accrue de neuromédiateurs pro-inflammatoires).</td>\n          </tr>\n          <tr>\n            <td><strong>Facteurs de gravité / résistance</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-etio\">Alcool</span></strong> et <strong><span class=\"kw-etio\">tabac</span></strong> : facteur de gravité et de résistance thérapeutique</li>\n                <li><strong>Surcharge pondérale</strong> : facteur de résistance au traitement</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Formes cliniques topographiques (à reconnaître)</h4>\n      <table class=\"matrix\">\n        <thead><tr><th>Forme</th><th>Présentation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Cuir chevelu</strong></td>\n            <td>Plaques circonscrites couvertes de larges squames traversées par les cheveux <em>ou</em> carapace recouvrante. <strong>Couronne rouge discrètement squameuse à la lisière antérieure</strong>. Rarement alopéciante.</td>\n          </tr>\n          <tr>\n            <td><strong>Unguéal</strong></td>\n            <td>\n              <ul>\n                <li>Ongles en <strong>« dé à coudre »</strong> (dépressions cupuliformes)</li>\n                <li><strong>Onycholyse</strong> + zone proximale couleur cuivrée</li>\n                <li><span class=\"kw-clinique\">Hyperkératose</span> sous-unguéale, paronychie, leuconychie</li>\n                <li>⚠️ Forme extrême : <strong>disparition de la tablette</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Inversé (plis)</strong></td>\n            <td>Intertrigo <strong>vernissé</strong>, bien limité. <strong>Pas de <span class=\"kw-clinique\">pustule</span>, pas de collerette périphérique</strong>. Confirmation : <span class=\"kw-clinique\">plaque</span> psoriasique à distance des plis.</td>\n          </tr>\n          <tr>\n            <td><strong>Palmo-plantaire</strong></td>\n            <td>Kératodermie en îlots ou diffuse, souvent fissuraire. Forme pustuleuse possible (<strong>pustulose palmo-plantaire</strong> — association possible au <strong>syndrome SAPHO</strong>).</td>\n          </tr>\n          <tr>\n            <td><strong>Muqueuses</strong></td>\n            <td>Linguale (glossite exfoliatrice marginée) · Génitale (lésions érythémateuses <span class=\"kw-alerte\">non squameuses</span>, aggravées par les rapports ⚠️).</td>\n          </tr>\n          <tr>\n            <td><strong>Visage (sébo-<span class=\"kw-clinique\">psoriasis</span>)</strong></td>\n            <td>Rare. Aspect de <strong><span class=\"kw-clinique\">dermatite</span> <span class=\"kw-clinique\">séborrhéique</span></strong> (sourcils, plis nasogéniens). Atteinte conque oreille + CAE possible.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 111 — Dermatoses faciales · 114 — Exanthème et érythrodermie · 116 — <span class=\"kw-clinique\">Prurit</span> · 325 — Effets indésirables des médicaments</em></p>","frequence":3},{"id":"117-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les trois formes graves de psoriasis","contenu":"<p>Trois grandes formes graves à reconnaître : <span class=\"kw-alerte\">érythrodermique</span>, <span class=\"kw-alerte\">pustuleux généralisé</span> et <span class=\"kw-alerte\">rhumatisme psoriasique</span>.</p>\n\n      <h4>1️⃣ <span class=\"kw-clinique\">Psoriasis</span> érythrodermique</h4>\n      <div class=\"callout callout-danger\">\n        <ul>\n          <li><strong>Définition</strong> : <span class=\"kw-clinique\">psoriasis</span> généralisé à <span class=\"kw-alerte\">&gt; 90 % de la surface cutanée</span> + <strong>desquamation abondante</strong></li>\n          <li><strong>Contexte</strong> : <span class=\"kw-clinique\">rebond après arrêt d’une corticothérapie générale</span> ++</li>\n          <li><strong>CAT</strong> : <span class=\"kw-alerte\">hospitalisation en milieu spécialisé 🏥</span></li>\n        </ul>\n      </div>\n\n      <h4>2️⃣ <span class=\"kw-clinique\">Psoriasis</span> pustuleux généralisé</h4>\n      <table >\n        <thead><tr><th>Item</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Apparition</strong></td>\n            <td>D’emblée ou complique un <span class=\"kw-clinique\">psoriasis</span> en plaques. Déclencheurs : <strong>médicaments</strong>, <strong><span class=\"kw-ci\">grossesse</span></strong>…</td>\n          </tr>\n          <tr>\n            <td><strong>Topographie</strong></td>\n            <td>Préférentielle : <strong>tronc</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Clinique</strong></td>\n            <td>\n              Début brutal (mais moins que <span class=\"kw-alerte\">PEAG</span>) :\n              <ul>\n                <li><span class=\"kw-alerte\">AEG + fièvre élevée</span></li>\n                <li>Placards rouge vif → <strong>pustules superficielles non folliculaires</strong></li>\n                <li>Confluence en larges nappes</li>\n                <li><span class=\"kw-clinique\">Évolution</span> secondairement <strong>érosive</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span></strong></td>\n            <td><span class=\"kw-alerte\">Pronostic vital pouvant être engagé 🔥</span></td>\n          </tr>\n          <tr>\n            <td><strong>Traitement</strong></td>\n            <td>Acitrétine · <span class=\"kw-ttt\">Méthotrexate</span> · <span class=\"kw-ttt\">Ciclosporine</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-def\">Diagnostic différentiel</span> ⚠️ — Pustuleux généralisé <span class=\"kw-bio\">vs</span> <span class=\"kw-alerte\">PEAG</span></strong>\n        <ul>\n          <li>Début moins brutal pour le <span class=\"kw-clinique\">psoriasis</span> pustuleux</li>\n          <li><span class=\"kw-clinique\">Évolution</span> plus prolongée</li>\n          <li>ATCD de <span class=\"kw-clinique\">psoriasis</span></li>\n          <li>❌ <strong><span class=\"kw-bio\">Histologie</span> ne permet pas de différencier</strong> : pustules spongiformes, non folliculaires et aseptiques (les différencient des pustules d’origine infectieuse)</li>\n        </ul>\n      </div>\n\n      <h4>3️⃣ Rhumatisme psoriasique</h4>\n      <ul>\n        <li>Retrouvé chez <strong><span class=\"kw-chiffre\">5 à 25 %</span></strong> des patients psoriasiques (jusqu’à <strong><span class=\"kw-chiffre\">25 %</span></strong> selon le collège)</li>\n        <li>→ détail dans l’objectif dédié « formes cliniques articulaires »</li>\n      </ul>\n\n      <h4>Cas particulier — <span class=\"kw-clinique\">Psoriasis</span> sur <span class=\"kw-etio\">VIH</span></h4>\n      <div class=\"callout callout-warn\">\n        <ul>\n          <li>Souvent <strong>grave</strong> et <strong>réfractaire aux traitements conventionnels</strong></li>\n          <li>Aspects possibles : en plaques, pustuleux ou érythrodermique</li>\n          <li>Difficile à distinguer d’une <span class=\"kw-clinique\">dermatite</span> <span class=\"kw-clinique\">séborrhéique</span> profuse</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 114 — Érythrodermie · 169 — Infection <span class=\"kw-etio\">VIH</span> · 325 — Effets indésirables des médicaments</em></p>","frequence":0},{"id":"117-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principaux diagnostics différentiels du psoriasis","contenu":"<p>Quatre grands DDx du <span class=\"kw-clinique\">psoriasis</span> en plaques classique. La <span class=\"kw-bio\">biopsie</span> aide en cas de doute (notamment pour les lymphomes cutanés).</p>\n\n      <h4>1. <span class=\"kw-etio\">Pityriasis</span> rosé de Gibert</h4>\n      <table >\n        <tbody>\n          <tr>\n            <td><strong>Cause</strong></td>\n            <td><span class=\"kw-clinique\">Éruption</span> d’origine inconnue (possiblement <strong><span class=\"kw-etio\">virale</span></strong>), souvent saisonnière.</td>\n          </tr>\n          <tr>\n            <td><strong>Avant <span class=\"kw-clinique\">éruption</span></strong></td>\n            <td><span class=\"kw-clinique\">Médaillon isolé</span> précédant l’<span class=\"kw-clinique\">éruption</span> pendant <strong><span class=\"kw-chiffre\">10-15 jours</span></strong>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Éruption</span></strong></td>\n            <td>\n              Macules rosées finement squameuses + médaillons centre clair en voie de guérison :\n              <ul>\n                <li>Racine des membres</li>\n                <li><strong>Tronc</strong> en « <strong>arbre de Noël</strong> » dans le dos</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>⭐ CAT</strong></td>\n            <td><span class=\"kw-bio\">Sérologies</span> <strong><span class=\"kw-etio\">VIH</span></strong> et <strong>TPHA/VDRL</strong> (syphilis).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Évolution</span></strong></td>\n            <td><span class=\"kw-clinique\">Guérison spontanée en <strong>6 à 8 semaines</strong></span> (sinon évoquer DDx).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>2. <span class=\"kw-clinique\">Dermatite</span> <span class=\"kw-clinique\">séborrhéique</span></h4>\n      <table >\n        <tbody>\n          <tr>\n            <td><strong>Faire la différence</strong></td>\n            <td>\n              <ul>\n                <li>Localisations : <strong>visage (plis nasogéniens)</strong>, cuir chevelu, région médiothoracique</li>\n                <li>Présence de <span class=\"kw-clinique\">psoriasis</span> à distance aide au diagnostic</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Difficulté</strong></td>\n            <td>Formes frontières possibles : <strong>sébo-<span class=\"kw-clinique\">psoriasis</span></strong>, dermite bipolaire du nourrisson.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>3. <span class=\"kw-clinique\">Eczéma</span> chronique</h4>\n      <table >\n        <tbody>\n          <tr>\n            <td><strong>Faire la différence</strong></td>\n            <td>\n              <ul>\n                <li><strong>Peu de squames</strong> · <strong>limites émiettées</strong> (<span class=\"kw-bio\">vs</span> bien limitées dans le <span class=\"kw-clinique\">psoriasis</span>)</li>\n                <li>Topographie : <strong>visage et plis</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Difficulté</strong></td>\n            <td>DDx avec <strong><span class=\"kw-clinique\">eczéma</span> <span class=\"kw-clinique\">nummulaire</span></strong> et <strong>eczémas palmo-plantaires</strong>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>4. Lymphomes cutanés</h4>\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-bio\">Biopsie</span> systématique en cas de doute ⚠️</strong> — Penser au <span class=\"kw-clinique\">syndrome de Sézary</span> devant un <span class=\"kw-clinique\">psoriasis</span> « érythrodermique » résistant au traitement.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 111 — Dermatoses faciales · 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 114 — Érythrodermie · 162 — IST</em></p>","frequence":0},{"id":"117-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic des formes cliniques articulaires du psoriasis","contenu":"<p>Le <span class=\"kw-def\">rhumatisme psoriasique</span> appartient aux <strong>spondyloarthrites</strong>. Atteinte articulaire <strong>hétérogène</strong> évoluant par poussées.</p>\n\n      <h4><span class=\"kw-def\">Épidémiologie</span> &amp; <span class=\"kw-etio\">génétique</span></h4>\n      <table >\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Prévalence</span></strong></td>\n            <td><strong><span class=\"kw-chiffre\">0,2 à 0,4 %</span></strong> en population générale · <strong><span class=\"kw-chiffre\">5 à 25 %</span></strong> chez les patients psoriasiques.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">HLA-B27</span></strong></td>\n            <td>Présent dans <strong><span class=\"kw-chiffre\">20 à 50 %</span></strong> des cas selon la forme : <strong>moins fréquent</strong> que dans les autres SpA, mais associé à l’<strong>atteinte axiale</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Chronologie</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Psoriasis</span> précède en général les manifestations rhumatologiques d’<strong>≈<span class=\"kw-chiffre\"> 10 ans</span></strong> :\n              <ul>\n                <li>Formes synchrones :<span class=\"kw-chiffre\"> 10-15 %</span></li>\n                <li><strong>« Rhumatisme psoriasique sans <span class=\"kw-clinique\">psoriasis</span> »</strong> (<span class=\"kw-chiffre\">10-15 %</span>) : signes articulaires précèdent les signes cutanés → <strong>ATCD familiaux de psoriasis = clé du diagnostic</strong> (critère CASPAR)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Localisations cutanées « zones bastions » devant faire chercher un <span class=\"kw-imagerie\">RP</span></h4>\n      <ul>\n        <li>Atteinte du <strong>cuir chevelu / scalp</strong></li>\n        <li>Atteinte <strong>unguéale</strong></li>\n        <li><span class=\"kw-clinique\">Psoriasis</span> <strong>inversé</strong> (sillon interfessier, plis rétro-auriculaires, axillaires, ombilic, plis inguinaux)</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        Le <strong>type</strong> de <span class=\"kw-clinique\">psoriasis</span> (vulgaire, en gouttes, pustuleux) et la <strong>sévérité cutanée</strong> ne sont <strong>pas corrélés</strong> à l’atteinte articulaire ❌ — contrairement à certaines localisations.\n      </div>\n\n      <h4>Les <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>4</span> g</span>rands tableaux cliniques + 2 rares</h4>\n      <table class=\"matrix\">\n        <thead><tr><th>Tableau</th><th>Présentation</th><th>Fréquence</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Atteinte isolée de l’IPD</strong> (doigt / orteil)</td>\n            <td>Souvent associée à un <span class=\"kw-clinique\">psoriasis</span> unguéal sus-jacent.<br><strong>Orteil de Bauer</strong> = psoriasis unguéal de l’orteil + arthrite IPD.</td>\n            <td><span class=\"kw-chiffre\">10-15 %</span></td>\n          </tr>\n          <tr>\n            <td><strong>Mono- ou oligoarthrite asymétrique</strong></td>\n            <td>\n              Grosses articulations <strong>ou</strong> orteils/doigts (<span class=\"kw-ttt\">IPP</span> et/ou IPD).<br>\n              <strong>Dactylite</strong> = la plus évocatrice : arthrite IPD + arthrite <span class=\"kw-ttt\">IPP</span> + ténosynovite des fléchisseurs (« <strong>doigt/orteil en saucisse</strong> »).\n            </td>\n            <td><span class=\"kw-chiffre\">15-40 %</span></td>\n          </tr>\n          <tr>\n            <td><strong>Polyarthrite séronégative</strong></td>\n            <td>\n              Peu destructrice, mais formes diffuses très destructrices possibles. Proche de la PR ⚠️ mais :\n              <ul>\n                <li><strong>Asymétrique</strong>, prédominance IPD (très rare dans PR)</li>\n                <li>Atteinte <strong>« tripolaire »</strong> (MCP + <span class=\"kw-ttt\">IPP</span> + IPD) d’un doigt</li>\n                <li><strong>Séronégative</strong> : pas d’ACPA, pas de FR</li>\n                <li>Radiologie discriminante</li>\n              </ul>\n            </td>\n            <td><span class=\"kw-chiffre\">20 %</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Spondyloarthrite</span> psoriasique</strong> (forme axiale)</td>\n            <td>\n              Proche de la SpA ankylosante. Association à <strong><span class=\"kw-bio\">HLA-B27</span></strong> 🧬. Rachialgies inflammatoires ± <strong>sacro-iliite</strong>. Atteinte périphérique associée dans ~<span class=\"kw-chiffre\">50 %</span> des cas.\n            </td>\n            <td><span class=\"kw-chiffre\">20 %</span></td>\n          </tr>\n          <tr>\n            <td><strong>Arthrite mutilante</strong></td>\n            <td>Formes gravissimes : ostéolyse des phalanges → aspect en <strong>« lorgnette »</strong>.</td>\n            <td>Exceptionnel</td>\n          </tr>\n          <tr>\n            <td><strong>Onycho-pachydermo-périostite</strong></td>\n            <td>Pathognomonique : <span class=\"kw-clinique\">psoriasis</span> unguéal + épaississement douloureux des parties molles + ostéopériostite radiologique.</td>\n            <td>Rare</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Biologie</h4>\n      <table >\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Syndrome inflammatoire</span></strong></td>\n            <td>Inconstant, surtout lors des poussées polyarticulaires.</td>\n          </tr>\n          <tr>\n            <td><strong>Facteur rhumatoïde</strong></td>\n            <td>Absent ou faible (<span class=\"kw-chiffre\">5 à 15 %</span> des malades). <strong><span class=\"kw-bio\">Anti-CCP</span> / ACPA généralement absents</strong> ❌.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">HLA-B27</span></strong></td>\n            <td><span class=\"kw-chiffre\">20 à 50 %</span> (selon la forme — plus fréquent dans les axiales).</td>\n          </tr>\n          <tr>\n            <td><strong>🔥 <span class=\"kw-def\">Comorbidités</span></strong></td>\n            <td><span class=\"kw-def\">Syndrome métabolique</span> : <strong><span class=\"kw-etio\">dyslipidémie</span></strong>, <strong>hyperuricémie</strong>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Radiologie — association destructrices ↔ reconstructrices</h4>\n      <table class=\"matrix\">\n        <thead><tr><th>Type</th><th>Lésions</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Destructrices</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Érosion</span> marginale, ostéolyse, progression périphérie → centre :\n              <ul>\n                <li>Image en <strong>« pointe de crayon » (pencil-in-cup)</strong></li>\n                <li>Ostéolyse complète, <strong>acro-ostéolyse des houppes phalangiennes</strong>, arthrite mutilante</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Reconstructrices</strong></td>\n            <td>Hyperostose, appositions périostées, périostite, enthésophytes (surtout rachis), ankylose. <strong>Permet de différencier de la PR</strong> ✅.</td>\n          </tr>\n          <tr>\n            <td><strong>Atteinte axiale</strong></td>\n            <td>Comme la SpA : sacro-iliite ± syndesmophytes.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Diagnostics différentiels</h4>\n      <ul>\n        <li><strong><span class=\"kw-def\">Polyarthrite rhumatoïde</span></strong></li>\n        <li>Autres SpA</li>\n        <li><strong>Arthrose digitale érosive</strong> (érosions centrales, aspect en « aile de mouette » — <span class=\"kw-bio\">vs</span> <span class=\"kw-imagerie\">RP</span> plus érosif et reconstructeur)</li>\n        <li><strong>Goutte</strong> : le <span class=\"kw-clinique\">psoriasis</span> est un FdR de goutte → arthrite aiguë des MI à évoquer systématiquement</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 54 — Boiterie · 197 — <span class=\"kw-def\">Spondyloarthrite</span> · 196 — <span class=\"kw-def\">Polyarthrite rhumatoïde</span> · 198 — Goutte</em></p>","frequence":1},{"id":"117-7","rang":"B","rubrique":"Diagnostic positif","titre":"Savoir reconnaître un psoriasis chez l’enfant","contenu":"<p>Le <span class=\"kw-clinique\">psoriasis</span> de l’enfant 👦🏻 présente des particularités sémiologiques et étiologiques importantes.</p>\n\n      <table >\n        <thead><tr><th>Item</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Contexte déclenchant</strong></td>\n            <td>Peut faire suite à une <span class=\"kw-clinique\">infection rhino-pharyngée streptococcique</span> (<span class=\"kw-etio\">streptocoque</span> β-hémolytique du groupe A).</td>\n          </tr>\n          <tr>\n            <td><strong>Mode d’<span class=\"kw-clinique\">évolution</span></strong></td>\n            <td>Souvent <strong>aigu</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Forme dominante</strong></td>\n            <td><span class=\"kw-clinique\">Psoriasis</span> <strong>en gouttes</strong> (chez l’enfant plus âgé et l’adolescent 🧑🏻).</td>\n          </tr>\n          <tr>\n            <td><strong>Topographie</strong></td>\n            <td>\n              <ul>\n                <li><strong>Zone du siège le plus souvent</strong> (= « <span class=\"kw-clinique\">psoriasis</span> des langes / napkin psoriasis »)</li>\n                <li><strong>Visage</strong> plus souvent atteint que chez l’adulte</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Conduite à tenir</strong> — devant un enfant avec <span class=\"kw-clinique\">éruption</span> psoriasique aiguë :\n        <ul>\n          <li>Rechercher une <strong>angine streptococcique</strong> récente (TDR)</li>\n          <li>Évoquer le <span class=\"kw-def\">diagnostic différentiel</span> : <strong><span class=\"kw-etio\">pityriasis</span> rosé de Gibert</strong>, <span class=\"kw-clinique\">eczéma</span>, dermatite <span class=\"kw-clinique\">séborrhéique</span></li>\n          <li>Bilan adapté à l’âge avant tout traitement systémique</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 49 — Puberté · 149 — Angines &amp; pharyngites</em></p>","frequence":0},{"id":"117-8","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principales pathologies associées au psoriasis","contenu":"<p>Le <span class=\"kw-clinique\">psoriasis</span> n’est <strong>pas qu’une maladie cutanée</strong> — il s’associe à un cortège de <span class=\"kw-def\">comorbidités</span> qui conditionnent le <span class=\"kw-def\">pronostic</span> et justifient une <span class=\"kw-def\">prise en charge multidisciplinaire</span>.</p>\n\n      <h4><span class=\"kw-def\">Comorbidités</span> à dépister systématiquement</h4>\n      <table class=\"matrix\">\n        <thead><tr><th>Famille</th><th>Détails</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Psychiatriques</strong></td>\n            <td>\n              <ul>\n                <li>Handicap social important · altération profonde de la <strong>qualité de vie</strong></li>\n                <li><span class=\"kw-clinique\">Syndrome dépressif</span> (même en dehors des formes graves)</li>\n                <li>Risque de <strong>suicide</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Conduites addictives</strong></td>\n            <td>\n              Association significative chez certains patients :\n              <ul>\n                <li><strong><span class=\"kw-etio\">Tabagisme</span></strong></li>\n                <li>Consommation excessive d’<strong><span class=\"kw-etio\">alcool</span></strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>🩺 Cardiovasculaires</strong></td>\n            <td>\n              <ul>\n                <li>Surrisque significatif de <span class=\"kw-alerte\">comorbidités cardiovasculaires</span></li>\n                <li><span class=\"kw-def\">HTA</span> · insuffisance coronarienne</li>\n                <li><strong><span class=\"kw-def\">Mortalité</span> précoce accrue dans les formes sévères 🏴‍☠️</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Métaboliques</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-def\">Syndrome métabolique</span></strong> (<span class=\"kw-etio\">obésité</span>, <span class=\"kw-def\">HTA</span>, <span class=\"kw-etio\">dyslipidémie</span>)</li>\n                <li>Risque de <strong><span class=\"kw-def\">diabète</span> type 2</strong> si non traité</li>\n                <li>Hyperuricémie</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Digestives</strong></td>\n            <td><strong><span class=\"kw-def\">MICI</span></strong> — surtout à connaître si on envisage une <span class=\"kw-ttt\">biothérapie</span> (anti-IL-17 <span class=\"kw-ci\">contre-indiqués</span> si <span class=\"kw-def\">MICI</span> non contrôlée).</td>\n          </tr>\n          <tr>\n            <td><strong>Rhumatologiques</strong></td>\n            <td><strong>Rhumatisme psoriasique</strong> chez <span class=\"kw-chiffre\">5-25 %</span> des patients (cf. objectif dédié).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Implications cliniques</strong>\n        <ul>\n          <li><span class=\"kw-def\">Dépistage</span> systématique des <span class=\"kw-def\">comorbidités</span> <span class=\"kw-bio\">CV</span> et métaboliques</li>\n          <li>Soutien psychologique / repérage du syndrome dépressif</li>\n          <li>Prise en charge multidisciplinaire (dermato, rhumato, médecin traitant, psy…)</li>\n          <li>Devant un patient avec <strong>lombalgies</strong> ou <strong>douleur du pied</strong> → <strong>RX systématiques</strong> à la recherche de <span class=\"kw-imagerie\">RP</span> (la présence d’un <span class=\"kw-imagerie\">RP</span> classe le <span class=\"kw-clinique\">psoriasis</span> comme grave)</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 66 — Diagnostic et conduite à tenir <span class=\"kw-def\">dépression</span> · 75 — Addictions · 224 — <span class=\"kw-def\">HTA</span> · 247 — <span class=\"kw-def\">Diabète</span> · 282 — <span class=\"kw-def\">MICI</span> · 285 — <span class=\"kw-clinique\">Diarrhée</span> chronique · 197 — <span class=\"kw-def\">Spondyloarthrite</span></em></p>","frequence":1},{"id":"117-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge thérapeutique du psoriasis","contenu":"<div class=\"callout callout-warn\">\n        <strong>Objectif global</strong> — les traitements actuels <span class=\"kw-alerte\">n’entraînent pas de guérison définitive</span> ❌. Le but est de <span class=\"kw-def\">réduire l’intensité des lésions</span> et d’<span class=\"kw-def\">améliorer la qualité de vie</span>.\n      </div>\n\n      <h4>Étape 1 — Évaluer la gravité &amp; le retentissement</h4>\n      <table >\n        <thead><tr><th>Échelle</th><th>Modérée à sévère si…</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Surface corporelle atteinte</strong></td>\n            <td><strong>&gt;<span class=\"kw-chiffre\"> 10 %</span></strong> (référence : <strong>1 paume =<span class=\"kw-chiffre\"> 1 %</span></strong>)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Score</span> PASI</strong> (<em><span class=\"kw-clinique\">Psoriasis</span> Area and Severity Index</em>)</td>\n            <td><strong>PASI &gt; 10</strong> — combine extension, <span class=\"kw-clinique\">érythème</span>, <span class=\"kw-ttt\">infiltration</span>, desquamation</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Score</span> DLQI</strong> (<em>Dermatology Life Quality Index</em>, 0-30)</td>\n            <td><strong>DLQI &gt; 10</strong> — retentissement sur la qualité de vie</td>\n          </tr>\n          <tr>\n            <td><strong>Forme grave</strong></td>\n            <td>Présence d’un rhumatisme psoriasique, érythrodermie, pustuleux généralisé.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Étape 2 — Choisir le traitement selon la sévérité</h4>\n\n      <h5>🟢 Forme légère à modérée (&lt;<span class=\"kw-chiffre\"> 10 %</span> surface)</h5>\n      <div class=\"obj-callout success\">\n        <strong>Traitement local suffit dans la majorité des cas</strong> :\n        <ul>\n          <li><strong><span class=\"kw-ttt\">Dermocorticoïdes</span></strong> d’activité forte (propionate de fluticasone, dipropionate de bétaméthasone) <em>en dehors du visage</em> ⭐</li>\n          <li><strong>Analogues vitamine D3</strong> : calcipotriol, tacalcitol, calcitriol</li>\n          <li><strong>Association <span class=\"kw-ttt\">dermocorticoïde</span> + calcipotriol</strong> (synergie ; efficacité supérieure aux monothérapies)</li>\n          <li>Préparation à base d’<strong>acide salicylique</strong> (<span class=\"kw-ttt\">kératolytique</span>) avant un autre traitement</li>\n          <li>Bains, <span class=\"kw-ttt\">émollients</span></li>\n        </ul>\n      </div>\n\n      <h5>🟠 Forme modérée à sévère (&gt;<span class=\"kw-chiffre\"> 30 %</span> ou résistance aux traitements locaux)</h5>\n      <p>Avec retentissement sur la qualité de vie :</p>\n      <ol>\n        <li><strong><span class=\"kw-ttt\">Photothérapie</span></strong> ± <span class=\"kw-ttt\">rétinoïdes</span> (rePUVA, <span class=\"kw-ttt\">UVB</span> TL-01)</li>\n        <li><span class=\"kw-ttt\">Rétinoïdes</span> seuls : <strong>acitrétine</strong></li>\n        <li><strong><span class=\"kw-ttt\">Méthotrexate</span></strong></li>\n        <li><strong><span class=\"kw-ttt\">Ciclosporine</span></strong></li>\n        <li><strong>Si échec ou <span class=\"kw-ci\">intolérance</span></strong> → <strong>aprémilast</strong> ou <strong>biothérapies</strong></li>\n      </ol>\n\n      <div class=\"callout callout-danger\">\n        <strong>⚠️ Annale</strong> — un traitement <strong>local seul</strong> est compté <strong>FAUX</strong> pour une forme de <span class=\"kw-clinique\">psoriasis</span> sévère.\n      </div>\n\n      <h5>🔴 Formes cliniques particulières</h5>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Psoriasis</span> pustuleux</strong> : acitrétine, <span class=\"kw-ttt\">méthotrexate</span>, <span class=\"kw-ttt\">ciclosporine</span></li>\n        <li><strong>Kératodermie palmo-plantaire invalidante</strong> : acitrétine, <span class=\"kw-ttt\">méthotrexate</span></li>\n        <li><strong>Rhumatisme psoriasique invalidant</strong> : <span class=\"kw-ttt\">méthotrexate</span>, anti-TNFα, anti-IL-12/IL-23, anti-IL-17</li>\n        <li><strong>Érythrodermie</strong> : <span class=\"kw-alerte\">hospitalisation</span> en milieu spécialisé</li>\n      </ul>\n\n      <h4>Étape 3 — Modalités d’administration des traitements généraux</h4>\n\n      <h5><span class=\"kw-ttt\">Dermocorticoïdes</span> (rappel pratique)</h5>\n      <table >\n        <tbody>\n          <tr>\n            <td><strong>Formes</strong></td>\n            <td>\n              <ul>\n                <li>Crème, pommade (<em><span class=\"kw-ci\">à éviter</span> dans les plis — macération</em>)</li>\n                <li>Lotion, mousse, shampoing au propionate de clobétasol → cuir chevelu</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Fréquence / durée</strong></td>\n            <td>\n              <ol>\n                <li>Attaque : <strong>1×/jour pendant <span class=\"kw-chiffre\">1 à 3 semaines</span></strong> (effet réservoir de la couche cornée)</li>\n                <li>Entretien intermittent possible : <strong>2×/semaine</strong></li>\n              </ol>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Optimisation</strong></td>\n            <td>Pansement occlusif / hydrocolloïde (surtout paumes &amp; plantes).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5><span class=\"kw-ttt\">Photothérapie</span></h5>\n      <table class=\"matrix\">\n        <thead><tr><th>Modalité</th><th>Détails</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>PUVAthérapie</strong></td>\n            <td><span class=\"kw-ttt\">UVA</span> + psoralène (8-MOP ou 5-MOP). <strong>2-3 séances/semaine</strong>, environ 20 séances. Photoprotection + <strong>lunettes noires</strong> obligatoires.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">UVB</span> TL-01 (spectre étroit)</strong></td>\n            <td>Pas de psoralène, efficacité comparable, <strong>moins carcinogène</strong>. 20-30 séances, 2-3/semaine.</td>\n          </tr>\n          <tr>\n            <td><strong>Autres</strong></td>\n            <td>rePUVA (acitrétine + <span class=\"kw-ttt\">PUVA</span>), photothérapies localisées paumes/plantes.</td>\n          </tr>\n          <tr>\n            <td><strong>⚠️ CI</strong></td>\n            <td>\n              <ul>\n                <li>ATCD de cancer cutané</li>\n                <li>Dermatose photo-aggravée</li>\n                <li><strong>Médicaments photosensibilisants</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>EI long terme</strong></td>\n            <td>Vieillissement cutané · <span class=\"kw-alerte\">cancers cutanés (carcinomes)</span> → <strong>pas d’utilisation au long cours</strong> · ne pas dépasser <strong>200 séances cumulées</strong>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Acitrétine (<span class=\"kw-ttt\">rétinoïde</span>)</h5>\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-ci\">Contre-indications</span></strong>\n        <ul>\n          <li>Anomalies du <span class=\"kw-bio\">bilan lipidique</span> ou hépatique</li>\n          <li>Femme en âge de procréer <strong>sans <span class=\"kw-ci\">contraception efficace</span></strong></li>\n          <li><strong><span class=\"kw-ci\">Grossesse</span> prévue dans les <span class=\"kw-chiffre\">3 ans</span></strong> qui suivent l’arrêt</li>\n          <li><span class=\"kw-ci\">Grossesse</span> · <span class=\"kw-ci\">allaitement</span></li>\n        </ul>\n      </div>\n\n      <h5><span class=\"kw-ttt\">Méthotrexate</span> (immunomodulateur)</h5>\n      <table >\n        <tbody>\n          <tr>\n            <td><strong>CI majeures</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-ci\">Grossesse</span></strong> · <strong><span class=\"kw-ci\">allaitement</span></strong></li>\n                <li><strong><span class=\"kw-etio\">Alcoolisme</span></strong></li>\n                <li><span class=\"kw-ci\">Insuffisance hépatique</span> sévère</li>\n                <li>IR : ClCr <strong>&lt;<span class=\"kw-chiffre\"> 20-30 mL</span>/min</strong></li>\n                <li>Dyscrasies sanguines : leucopénie &lt; <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> G</span>, thrombopénie &lt; <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>50</span> G</span>, anémie &lt; 9</li>\n                <li>Infections graves : <strong><span class=\"kw-def\">tuberculose</span></strong>, <strong><span class=\"kw-etio\">VIH</span></strong></li>\n                <li>Ulcères buccaux / GI évolutifs</li>\n                <li>Vaccins vivants concomitants</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ci\">Bilan pré-thérapeutique</span></strong></td>\n            <td>\n              <ul>\n                <li>Mise à jour calendrier vaccinal (<span class=\"kw-chiffre\">2 semaines</span> avant) · <strong>vaccin anti-<span class=\"kw-etio\">pneumocoque</span> + anti-grippal</strong></li>\n                <li><span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">bilan rénal</span> &amp; hépatique, <span class=\"kw-bio\">albuminémie</span></li>\n                <li><strong>RX thorax</strong></li>\n                <li><span class=\"kw-bio\">Sérologies</span> <strong><span class=\"kw-etio\">VHB</span> · <span class=\"kw-etio\">VHC</span> · VIH</strong> ± VHE</li>\n                <li><span class=\"kw-bio\">Électrophorèse des protéines sériques</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>EI</strong></td>\n            <td>\n              <ul>\n                <li><strong>Hématologiques</strong> : cytopénies, macrocytose</li>\n                <li>Digestifs : mucite, <span class=\"kw-clinique\">nausées</span></li>\n                <li>Hépatiques : ↑ transaminases, fibrose</li>\n                <li>Rénaux : IR (toxicité tubulaire)</li>\n                <li>Cutanés : <span class=\"kw-clinique\">prurit</span>, <span class=\"kw-clinique\">érythème</span>, photosensibilisation</li>\n                <li><strong>Respiratoires</strong> : pneumopathie d’<span class=\"kw-ci\">hypersensibilité</span>, fibrose pulmonaire</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5><span class=\"kw-ttt\">Ciclosporine</span> (<span class=\"kw-ttt\">immunosuppresseur</span>)</h5>\n      <table >\n        <tbody>\n          <tr>\n            <td><strong>CI</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-def\">HTA</span></strong></li>\n                <li><span class=\"kw-ci\">Insuffisance rénale</span></li>\n                <li><strong>ATCD de néoplasie</strong></li>\n                <li>Infection chronique</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>⭐ EI</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-def\">HTA</span> ⭐️</strong></li>\n                <li>Hypertrichose</li>\n                <li>Néphrotoxicité (toxicité tubulaire directe)</li>\n                <li>Hyperplasie gingivale</li>\n                <li>Cancers cutanés</li>\n                <li>Nombreuses interactions médicamenteuses</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Biothérapies (biomédicaments)</h5>\n      <table >\n        <tbody>\n          <tr>\n            <td><strong>Indication</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Psoriasis</span> modéré à sévère avec retentissement sur la QdV :\n              <strong><span class=\"kw-ci\">intolérance</span> / inefficacité / <span class=\"kw-ci\">contre-indication</span> à <span class=\"kw-chiffre\">≥ 2</span> traitements généraux</strong> (dont <span class=\"kw-ttt\">méthotrexate</span>, <span class=\"kw-ttt\">ciclosporine</span> et <span class=\"kw-ttt\">photothérapie</span>).\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Molécules</strong></td>\n            <td>\n              <ul>\n                <li><strong>Anti-TNFα</strong> : <span class=\"kw-ttt\">étanercept</span>, <span class=\"kw-ttt\">infliximab</span>, <span class=\"kw-ttt\">adalimumab</span>, certolizumab</li>\n                <li><strong>Anti-IL-12 / IL-23</strong> (sous-unité p40) : <span class=\"kw-ttt\">ustékinumab</span></li>\n                <li><strong>Anti-IL-17</strong> : sécukinumab, ixékizumab, brodalumab</li>\n                <li><strong>Anti-IL-23</strong> (sous-unité p19) : <span class=\"kw-ttt\">guselkumab</span>, rizankizumab, tildrakizumab</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Règles de prescription</strong></td>\n            <td>\n              Réservé au spécialiste, <strong>prescription initiale hospitalière</strong>, renouvellement annuel en milieu hospitalier.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>⚠️ Piège</strong></td>\n            <td>\n              Les <strong>anti-TNFα</strong> peuvent paradoxalement induire une dermatose érythémato-squameuse simulant un <span class=\"kw-clinique\">psoriasis</span> (<strong>réactions psoriasiformes paradoxales</strong>).\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Aprémilast (immunomodulateur ciblé)</h4>\n      <p>Inhibiteur de la phosphodiestérase 4 — utilisé en cas d’<strong>échec, <span class=\"kw-ci\">contre-indication</span> ou <span class=\"kw-ci\">intolérance</span></strong> aux autres traitements systémiques (<span class=\"kw-ttt\">ciclosporine</span>, <span class=\"kw-ttt\">méthotrexate</span>, <span class=\"kw-ttt\">PUVA</span>).</p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 197 — <span class=\"kw-def\">Spondyloarthrite</span> · 196 — PR · 325 — Effets indésirables des médicaments · 326 — Bon usage des médicaments · 146 — Vaccinations · 202 — Biothérapies</em></p>","frequence":4}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré d'<span class=\"kw-alerte\">urgence</span> :</strong> le <span class=\"kw-clinique\">psoriasis</span> commun est une <span class=\"kw-def\">dermatose chronique</span> non urgente, mais 3 <span class=\"kw-alerte\">formes graves</span> imposent une prise en charge urgente.<br><strong><span class=\"kw-alerte\"><span class=\"kw-def\">Pronostic</span> vital</span> :</strong> le <span class=\"kw-alerte\">psoriasis pustuleux généralisé</span> peut <span class=\"kw-alerte\">mettre en jeu le pronostic vital</span>.<br><strong>1er geste :</strong> devant un <span class=\"kw-alerte\">psoriasis érythrodermique</span> (> <span class=\"kw-chiffre\">90 %</span> de la surface), <span class=\"kw-ttt\">hospitalisation en milieu spécialisé</span>.</p>","hospit":"<p><strong>Ambulatoire :</strong> formes communes légères à modérées (atteinte < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">10 %</span></span>) traitées localement.<br><strong>Avis spécialisé :</strong> <span class=\"kw-ttt\">dermatologue</span> pour les formes modérées à sévères relevant d'un traitement systémique.<br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> <span class=\"kw-alerte\">psoriasis érythrodermique</span> en milieu spécialisé.<br><strong>Prescription :</strong> <span class=\"kw-ttt\">biothérapies</span> réservées au spécialiste, à <span class=\"kw-ttt\">prescription initiale hospitalière</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Psoriasis érythrodermique</span> : généralisé à > <span class=\"kw-chiffre\">90 %</span> de la surface cutanée + <span class=\"kw-clinique\">desquamation abondante</span></li><li><span class=\"kw-alerte\">Psoriasis pustuleux généralisé</span> : début brutal, <span class=\"kw-clinique\">AEG</span> + <span class=\"kw-clinique\">fièvre élevée</span>, <span class=\"kw-clinique\">pustules superficielles non folliculaires</span> → <span class=\"kw-alerte\">pronostic vital</span> en jeu</li><li><span class=\"kw-etio\">Rhumatisme psoriasique</span> (<span class=\"kw-chiffre\">25 %</span> des malades) : sa présence classe directement le <span class=\"kw-clinique\">psoriasis</span> comme grave</li><li>Surface atteinte > <span class=\"kw-chiffre\">10 %</span>, <span class=\"kw-chiffre\">PASI > 10</span> ou <span class=\"kw-chiffre\">DLQI > 10</span></li><li><span class=\"kw-alerte\">Rebond</span> après arrêt d'une <span class=\"kw-ttt\">corticothérapie générale</span> → développement de formes graves (érythrodermique, pustuleux généralisé)</li><li>Surrisque de <span class=\"kw-etio\">comorbidités cardiovasculaires</span>, de <span class=\"kw-etio\">syndrome métabolique</span>, de <span class=\"kw-etio\">syndrome dépressif</span> et <span class=\"kw-def\">mortalité</span> précoce dans le <span class=\"kw-clinique\">psoriasis</span> sévère</li></ul>","principes":"<p><strong>Objectif :</strong> les traitements n'entraînent <span class=\"kw-def\">pas de guérison définitive</span> ; ils visent à réduire les lésions et améliorer la qualité de vie. Le choix dépend de la <span class=\"kw-def\">sévérité</span>.</p><p><strong>Évaluer la sévérité avant de traiter</strong></p><ul><li>Surface corporelle atteinte (paume = <span class=\"kw-chiffre\">1 %</span>) : modéré à sévère si > <span class=\"kw-chiffre\">10 %</span></li><li><span class=\"kw-def\">Score</span> <span class=\"kw-chiffre\">PASI > 10</span> (extension, <span class=\"kw-clinique\">érythème</span>, <span class=\"kw-ttt\">infiltration</span>, squames)</li><li>Retentissement sur la qualité de vie : <span class=\"kw-chiffre\">DLQI > 10</span></li><li>Rechercher une <span class=\"kw-alerte\">forme grave</span> ou un <span class=\"kw-etio\">rhumatisme psoriasique</span> (<span class=\"kw-imagerie\">radiographies</span> si lombalgie ou douleur du pied)</li></ul><p><strong>Forme légère à modérée (< 10 %)</strong></p><p>Traitement local suffisant dans la majorité des cas</p><ul><li><span class=\"kw-ttt\">Dermocorticoïdes</span> d'activité forte (hors visage)</li><li><span class=\"kw-ttt\">Analogues de la vitamine D3</span> (calcipotriol, tacalcitol, calcitriol)</li><li><span class=\"kw-ttt\">Association dermocorticoïde + calcipotriol</span> (synergie, supérieure à la monothérapie)</li></ul><p><strong>Forme modérée à sévère (<span class=\"kw-chiffre\">> 30 %</span> ou résistance aux topiques)</strong></p><p>Si échec ou <span class=\"kw-ci\">intolérance</span> → <span class=\"kw-ttt\">aprémilast</span> ou <span class=\"kw-ttt\">biothérapies</span></p><ul><li><span class=\"kw-ttt\">Photothérapie</span> (<span class=\"kw-ttt\">PUVA</span> ou UVB TL-01) ± <span class=\"kw-ttt\">rétinoïdes</span></li><li><span class=\"kw-ttt\">Acitrétine</span> (<span class=\"kw-ttt\">rétinoïde</span>)</li><li><span class=\"kw-ttt\">Méthotrexate</span> (immunomodulateur)</li><li><span class=\"kw-ttt\">Ciclosporine</span> (<span class=\"kw-ttt\">immunosuppresseur</span>)</li></ul><p><strong>Biothérapies</strong></p><p>Indiquées si <span class=\"kw-ci\">intolérance, inefficacité ou contre-indication</span> à ≥ <span class=\"kw-chiffre\">2</span> traitements généraux (dont <span class=\"kw-ttt\">méthotrexate</span>, <span class=\"kw-ttt\">ciclosporine</span>, <span class=\"kw-ttt\">photothérapie</span>)</p><ul><li>Anti-<span class=\"kw-ttt\">TNFα</span> : <span class=\"kw-ttt\">étanercept</span>, <span class=\"kw-ttt\">infliximab</span>, <span class=\"kw-ttt\">adalimumab</span>, certolizumab</li><li>Anti-<span class=\"kw-ttt\">IL-17</span> : sécukinumab</li><li>Anti-<span class=\"kw-ttt\">IL-12/IL-23</span> : <span class=\"kw-ttt\">ustékinumab</span></li><li>Anti-<span class=\"kw-ttt\">IL-23</span> : <span class=\"kw-ttt\">guselkumab</span></li></ul><p><strong>Formes cliniques particulières</strong></p><ul><li><span class=\"kw-clinique\">Psoriasis</span> pustuleux : <span class=\"kw-ttt\">acitrétine</span>, <span class=\"kw-ttt\">méthotrexate</span>, <span class=\"kw-ttt\">ciclosporine</span></li><li>Kératodermie palmo-plantaire invalidante : <span class=\"kw-ttt\">acitrétine</span>, <span class=\"kw-ttt\">méthotrexate</span></li><li>Rhumatisme psoriasique invalidant : <span class=\"kw-ttt\">méthotrexate</span>, <span class=\"kw-ttt\">anti-TNFα</span>, <span class=\"kw-ttt\">anti-IL-12/23</span>, <span class=\"kw-ttt\">anti-IL-17</span></li></ul><p><strong>Mesures associées</strong></p><ul><li>Éviction des facteurs aggravants : <span class=\"kw-ttt\">β-bloquants</span>, <span class=\"kw-ci\">arrêt brutal d'une corticothérapie générale</span> (risque de rebond)</li><li>Lutte contre <span class=\"kw-etio\">alcool</span> et <span class=\"kw-etio\">tabac</span> (facteurs de gravité et de résistance thérapeutique)</li><li>Prise en charge multidisciplinaire des <span class=\"kw-etio\">comorbidités</span> (cardiovasculaires, métaboliques, dépression)</li></ul>","suivi":"<p><strong><span class=\"kw-clinique\">Évolution</span> :</strong> <span class=\"kw-def\">chronique</span>, poussées imprévisibles, rémissions plus fréquentes <span class=\"kw-clinique\">l'été</span> (effet bénéfique des <span class=\"kw-etio\">UV</span>).<br><strong>Évaluation :</strong> surface corporelle, <span class=\"kw-chiffre\">PASI</span> et retentissement <span class=\"kw-chiffre\">DLQI</span> à chaque <span class=\"kw-def\">réévaluation</span>.<br><strong><span class=\"kw-ttt\">Photothérapie</span> :</strong> tenir compte de la dose cumulée (< <span class=\"kw-chiffre\">200 séances</span>), <span class=\"kw-alerte\">surveillance cutanée prolongée</span> (risque de <span class=\"kw-etio\">carcinomes</span>).<br><strong><span class=\"kw-ttt\">Méthotrexate</span> :</strong> <span class=\"kw-bio\">NFS</span>, bilan <span class=\"kw-bio\">hépatique</span> et <span class=\"kw-bio\">rénal</span>.<br><strong><span class=\"kw-def\">Comorbidités</span> :</strong> <span class=\"kw-def\">dépistage</span> du <span class=\"kw-etio\">syndrome métabolique</span>, du risque <span class=\"kw-etio\">cardiovasculaire</span> et du <span class=\"kw-etio\">syndrome dépressif</span>.</p>"},"liensGlobaux":[{"href":"https://www.lecofer.org/item-cours-1-6-0.php","label":"Collège COFER — Rhumatismes inflammatoires"},{"href":"https://radiopaedia.org/articles/psoriatic-arthritis","label":"Radiopaedia : Psoriatic arthritis"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Psoriasis confirmé — Diagnostic clinique (biopsie seulement si doute diagnostique)","detail":"<h4>CAT — Prise en charge thérapeutique du <span class=\"kw-clinique\">psoriasis</span> — Du diagnostic clinique au choix thérapeutique selon la sévérité</h4>","branches":[{"to":"q-grave","label":"Diagnostic posé","color":"blue"}]},{"id":"q-grave","kind":"decision","label":"Forme grave de psoriasis ? — Érythrodermie · pustuleux généralisé · rhumatisme psoriasique","branches":[{"to":"t-grave","label":"Oui","color":"red"},{"to":"q-severite","label":"Non","color":"green"}]},{"id":"t-grave","kind":"terminal","label":"Hospitalisation / avis spécialisé + traitement systémique","color":"red","detail":"<h4>Formes concernées</h4><ul><li><span class=\"kw-alerte\">Psoriasis érythrodermique</span> (> <span class=\"kw-chiffre\">90 %</span> de la surface)</li><li><span class=\"kw-alerte\">Psoriasis pustuleux généralisé</span> (<span class=\"kw-alerte\">pronostic vital</span> en jeu)</li><li><span class=\"kw-etio\">Rhumatisme psoriasique</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Hospitalisation en milieu spécialisé</span> pour le <span class=\"kw-clinique\">psoriasis</span> érythrodermique</li><li>Avis <span class=\"kw-ttt\">dermatologique</span> spécialisé</li></ul><h4>Traitement</h4><ul><li>Pustuleux : <span class=\"kw-ttt\">acitrétine</span>, <span class=\"kw-ttt\">méthotrexate</span>, <span class=\"kw-ttt\">ciclosporine</span></li><li>Rhumatisme psoriasique invalidant : <span class=\"kw-ttt\">méthotrexate</span>, <span class=\"kw-ttt\">anti-TNFα</span>, <span class=\"kw-ttt\">anti-IL-12/23</span>, <span class=\"kw-ttt\">anti-IL-17</span></li></ul>"},{"id":"q-severite","kind":"decision","label":"Évaluer la sévérité — Surface corporelle · PASI · DLQI","branches":[{"to":"t-local","label":"Légère : < 10 %, PASI < 10, DLQI < 10","color":"green"},{"to":"q-echec","label":"Modérée-sévère : > 10 % / PASI > 10 / DLQI > 10 + retentissement","color":"amber"}]},{"id":"t-local","kind":"terminal","label":"Traitement local en ambulatoire","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Dermocorticoïdes</span> d'activité forte (hors visage)</li><li><span class=\"kw-ttt\">Analogues de la vitamine D3</span> (calcipotriol, tacalcitol, calcitriol)</li><li><span class=\"kw-ttt\">Association dermocorticoïde + calcipotriol</span> (synergie)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Traitement d'attaque <span class=\"kw-chiffre\">1 fois/jour</span> pendant <span class=\"kw-chiffre\">1 à 3 semaines</span></li><li>Entretien intermittent <span class=\"kw-chiffre\">2 fois/semaine</span> possible</li></ul>"},{"id":"q-echec","kind":"decision","label":"Échec / intolérance / CI à ≥ 2 traitements généraux ? — Parmi méthotrexate, ciclosporine, photothérapie","branches":[{"to":"t-systemique","label":"Non (1re intention)","color":"amber"},{"to":"t-biotherapie","label":"Oui","color":"amber"}]},{"id":"t-systemique","kind":"terminal","label":"Traitement systémique de 1re intention","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Photothérapie</span> (<span class=\"kw-ttt\">PUVA</span> ou UVB TL-01) ± <span class=\"kw-ttt\">rétinoïdes</span></li><li><span class=\"kw-ttt\">Acitrétine</span> (<span class=\"kw-ttt\">rétinoïde</span>)</li><li><span class=\"kw-ttt\">Méthotrexate</span> (immunomodulateur)</li><li><span class=\"kw-ttt\">Ciclosporine</span> (<span class=\"kw-ttt\">immunosuppresseur</span>)</li></ul><h4><span class=\"kw-ci\">Contre-indications</span> clés</h4><ul><li>Acitrétine : <span class=\"kw-ci\">grossesse</span> (et projet de <span class=\"kw-ci\">grossesse</span> dans les <span class=\"kw-chiffre\">3 ans</span> suivant l'arrêt)</li><li><span class=\"kw-ttt\">Méthotrexate</span> : <span class=\"kw-ci\">grossesse</span>, <span class=\"kw-ci\">alcoolisme</span>, <span class=\"kw-ci\">insuffisance hépatique ou rénale</span></li><li><span class=\"kw-ttt\">Ciclosporine</span> : <span class=\"kw-ci\">HTA</span>, <span class=\"kw-ci\">insuffisance rénale</span>, <span class=\"kw-ci\">ATCD de néoplasie</span></li></ul>"},{"id":"t-biotherapie","kind":"terminal","label":"Biothérapie","color":"amber","detail":"<h4>Indication</h4><ul><li><span class=\"kw-clinique\">Psoriasis</span> modéré à sévère avec retentissement, après <span class=\"kw-ci\">intolérance, inefficacité ou contre-indication</span> à ≥ <span class=\"kw-chiffre\">2</span> traitements généraux</li></ul><h4>Molécules</h4><ul><li>Anti-<span class=\"kw-ttt\">TNFα</span> : <span class=\"kw-ttt\">étanercept</span>, <span class=\"kw-ttt\">infliximab</span>, <span class=\"kw-ttt\">adalimumab</span>, certolizumab</li><li>Anti-<span class=\"kw-ttt\">IL-17</span> : sécukinumab</li><li>Anti-<span class=\"kw-ttt\">IL-12/IL-23</span> : <span class=\"kw-ttt\">ustékinumab</span></li><li>Anti-<span class=\"kw-ttt\">IL-23</span> : <span class=\"kw-ttt\">guselkumab</span></li><li>± <span class=\"kw-ttt\">aprémilast</span> en cas d'échec ou d'<span class=\"kw-ci\">intolérance</span></li></ul><h4>Conduite</h4><ul><li>Prescription réservée au <span class=\"kw-ttt\">spécialiste</span>, à <span class=\"kw-ttt\">prescription initiale hospitalière</span></li></ul>"}]},"cards":[{"i":"2499398324cb","n":117,"o":"117-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un psoriasis en plaques classique","q":"Quels sont les signes cliniques du grattage caractéristiques du psoriasis en plaques ?","a":"<p>Les signes cliniques du grattage caractéristiques du psoriasis en plaques sont :</p><ul><li>La <strong>tache de bougie</strong> : blanchiment de la plaque après grattage.</li><li>La <strong>rosée sanglante</strong> (signe d’Auspitz) : apparition de petits points hémorragiques après le décollement des dernières lamelles squameuses.</li></ul>"},{"i":"2b7a7fd342ef","n":117,"o":"117-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un psoriasis en plaques classique","q":"Quelles sont les caractéristiques de la lésion élémentaire typique du psoriasis en plaques ?","a":"<p>La lésion élémentaire typique du psoriasis est une <strong>papule érythémato-squameuse</strong>. Elle est bien limitée, arrondie, ovalaire ou polycyclique, recouverte de <strong>squames</strong> épaisses ou partiellement décapées, laissant apparaître un érythème sous-jacent.</p>"},{"i":"5546df074f48","n":117,"o":"117-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un psoriasis en plaques classique","q":"Quels sont les symptômes, signes associés et l'évolution typique du psoriasis en plaques ?","a":"<p>Le psoriasis en plaques classique s'accompagne rarement de symptômes généraux. Il est <strong>non contagieux</strong>. Un <strong>prurit</strong> est présent lors des poussées dans 60% des cas, et les lésions peuvent être douloureuses (paumes, plantes) avec des fissures.</p><p>Son évolution est <strong>chronique</strong>, quasi-continue ou par poussées entrecoupées de rémissions, souvent imprévisibles. Les rémissions sont plus fréquentes l'été. La régression se fait <strong>sans cicatrice</strong>.</p>"},{"i":"760da1fa6f30","n":117,"o":"117-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un psoriasis en plaques classique","q":"Comment est majoritairement réalisé le diagnostic de psoriasis en plaques classique ?","a":"<p>Dans la très grande majorité des cas, le diagnostic de psoriasis en plaques classique est <strong>clinique</strong>. Une biopsie cutanée n'est indiquée qu'en cas de doute diagnostique devant des lésions atypiques.</p>"},{"i":"944ac72bcce7","n":117,"o":"117-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un psoriasis en plaques classique","q":"Qu'est-ce que le phénomène de Koebner dans le psoriasis ?","a":"<p>Le phénomène de Koebner, ou <strong>phénomène isomorphe de Koebner</strong>, désigne l'apparition de nouvelles lésions de psoriasis sur des <strong>zones de traumatismes cutanés</strong> (griffures, vaccination, chirurgie, coups de soleil), qui ont un rôle d'aggravation du psoriasis existant.</p>"},{"i":"b72c84c73165","n":117,"o":"117-3","u":"Diagnostic positif","t":"Connaître les modalités du diagnostic d’un psoriasis en plaques classique","q":"Quelles sont les localisations préférentielles du psoriasis en plaques classique ?","a":"<p>Le psoriasis en plaques classique se localise sur les « <strong>zones bastions</strong> », exposées aux frottements et traumatismes, de manière multiple et symétrique. Il s'agit des :</p><ul><li><strong>Coudes</strong> et bord cubital de l'avant-bras.</li><li><strong>Genoux</strong> et jambes.</li><li>Région <strong>lombo-sacrée</strong>.</li><li><strong>Cuir chevelu</strong>.</li><li><strong>Ongles</strong>, <strong>paumes</strong>, <strong>plantes</strong>.</li><li>Discrètement : ombilic, conduit auditif externe.</li></ul><p>Le <strong>visage est habituellement respecté</strong> dans la forme classique.</p>"},{"i":"416824eb744d","n":117,"o":"117-8","u":"Suivi et/ou pronostic","t":"Connaître les principales pathologies associées au psoriasis","q":"Quelles sont les comorbidités digestives et rhumatologiques fréquemment associées au psoriasis ?","a":"<p>Les comorbidités digestives associées au psoriasis sont les <strong>MICI (Maladies Inflammatoires Chroniques de l'Intestin)</strong>. Il est important de les connaître car les anti-IL-17 sont contre-indiqués en cas de MICI non contrôlée. La principale comorbidité rhumatologique est le <strong>rhumatisme psoriasique</strong>, qui affecte <strong>5 à 25 %</strong> des patients et est un signe de psoriasis grave.</p>"},{"i":"5766bf0c19e5","n":117,"o":"117-8","u":"Suivi et/ou pronostic","t":"Connaître les principales pathologies associées au psoriasis","q":"Quelles sont les principales comorbidités psychiatriques associées au psoriasis ?","a":"<p>Les comorbidités psychiatriques associées au psoriasis incluent un <strong>handicap social important</strong>, une <strong>altération profonde de la qualité de vie</strong>, un <strong>syndrome dépressif</strong> (y compris dans les formes non sévères), un <strong>risque de suicide accru</strong>, et des <strong>conduites addictives</strong> (tabagisme, consommation excessive d'alcool).</p>"},{"i":"6bd46731f0cb","n":117,"o":"117-8","u":"Suivi et/ou pronostic","t":"Connaître les principales pathologies associées au psoriasis","q":"Quelles sont les comorbidités cardiovasculaires et métaboliques associées au psoriasis, et pourquoi leur dépistage est-il important ?","a":"<p>Les comorbidités cardiovasculaires associées au psoriasis sont l'<strong>HTA</strong> et l'<strong>insuffisance coronarienne</strong>, avec une <strong>mortalité précoce accrue</strong> dans les formes sévères. Les comorbidités métaboliques sont le <strong>syndrome métabolique</strong> (obésité, HTA, dyslipidémie), le <strong>risque de diabète de type 2</strong> et l'<strong>hyperuricémie</strong>. Leur dépistage est crucial en raison d'un <strong>surrisque significatif</strong> qui conditionne le pronostic.</p>"},{"i":"f82107d9ac07","n":117,"o":"117-8","u":"Suivi et/ou pronostic","t":"Connaître les principales pathologies associées au psoriasis","q":"Quelle est l'approche de prise en charge des comorbidités associées au psoriasis ?","a":"<p>La prise en charge des comorbidités associées au psoriasis est <strong>multidisciplinaire</strong>, impliquant dermatologue, rhumatologue, médecin traitant et psychiatre. Elle comprend le <strong>dépistage systématique</strong> des comorbidités cardiovasculaires et métaboliques, le <strong>soutien psychologique</strong> et le repérage du syndrome dépressif. En cas de lombalgies ou douleurs du pied, une <strong>radiographie systématique</strong> est recommandée à la recherche d'un rhumatisme psoriasique.</p>"}]};